insert into public.topics (id, subject, grade, name, unit, kazanim, sort, planned_start, curriculum) values
  ('pa.g2.ela.story-key-details', 'ela', 2, 'Who, what, where, when, why in a story', 'Reading Literature', 'PA CC.1.3.2.B: Ask and answer who, what, where, when, why and how questions to show understanding of key details in a story.', 0, '2026-09-02', 'us-pa'),
  ('pa.g2.ela.long-short-vowels', 'ela', 2, 'Long and short vowel sounds', 'Foundational Skills', 'PA CC.1.1.2.D: Tell long and short vowels apart in regularly spelled one-syllable words and decode two-syllable words with long vowels.', 1, '2026-09-09', 'us-pa'),
  ('pa.g2.ela.main-idea', 'ela', 2, 'Main idea of a text', 'Reading Informational Text', 'PA CC.1.2.2.A: Identify the main idea of a multiparagraph text and the focus of specific paragraphs within it.', 2, '2026-09-23', 'us-pa'),
  ('pa.g2.ela.story-central-message', 'ela', 2, 'Central message of a story', 'Reading Literature', 'PA CC.1.3.2.A: Recount a story and determine its central message, lesson, or moral.', 3, '2026-10-07', 'us-pa'),
  ('pa.g2.ela.capitalize-proper-nouns', 'ela', 2, 'Capital letters for proper nouns', 'Conventions', 'PA CC.1.4.2.F, CC.1.4.2.L: Use grade-level conventions of standard English: capitalize proper nouns such as names, places, days and months.', 4, '2026-10-21', 'us-pa'),
  ('pa.g2.ela.prefixes-suffixes', 'ela', 2, 'Words with prefixes and suffixes', 'Foundational Skills', 'PA CC.1.1.2.D: Decode and understand words with common prefixes and suffixes (un-, re-, -ful, -less, -ly).', 5, '2026-11-04', 'us-pa'),
  ('pa.g2.ela.characters-respond', 'ela', 2, 'How characters respond to events', 'Reading Literature', 'PA CC.1.3.2.C: Describe how characters in a story respond to major events and challenges.', 6, '2026-11-18', 'us-pa'),
  ('pa.g2.ela.multiple-meaning-words', 'ela', 2, 'Words with more than one meaning', 'Vocabulary', 'PA CC.1.2.2.F, CC.1.2.2.K, CC.1.3.2.I: Determine the meaning of unknown and multiple-meaning words and phrases as they are used in a grade-level text.', 7, '2026-12-02', 'us-pa'),
  ('pa.g2.ela.text-features', 'ela', 2, 'Text features: titles, headings, glossary', 'Reading Informational Text', 'PA CC.1.2.2.E: Use text features and search tools (headings, bold words, glossary, index) to find key facts in a text quickly.', 8, '2026-12-16', 'us-pa'),
  ('pa.g2.ela.commas-apostrophes', 'ela', 2, 'Commas and apostrophes', 'Conventions', 'PA CC.1.4.2.F, CC.1.4.2.R: Use commas and apostrophes correctly, including apostrophes in contractions and to show possession.', 9, '2027-01-13', 'us-pa'),
  ('pa.g2.ela.events-and-steps', 'ela', 2, 'Order of events and steps', 'Reading Informational Text', 'PA CC.1.2.2.C: Describe the connection between a series of events, ideas, or steps in a procedure within a text.', 10, '2027-01-27', 'us-pa'),
  ('pa.g2.ela.story-beginning-ending', 'ela', 2, 'Beginning, middle and end of a story', 'Reading Literature', 'PA CC.1.3.2.E: Describe the structure of a story: how the beginning introduces it and how the ending concludes the action.', 11, '2027-02-10', 'us-pa'),
  ('pa.g2.ela.author-reasons', 'ela', 2, 'Reasons that support the author''s points', 'Reading Informational Text', 'PA CC.1.2.2.H: Describe how reasons support specific points the author makes in a text.', 12, '2027-03-03', 'us-pa'),
  ('pa.g2.ela.spelling-patterns', 'ela', 2, 'Spelling patterns', 'Conventions', 'PA CC.1.4.2.L, CC.1.4.2.R: Spell words correctly by drawing on common spelling patterns.', 13, '2027-03-24', 'us-pa'),
  ('pa.g2.ela.compare-two-texts', 'ela', 2, 'Compare two texts or story versions', 'Reading Informational Text', 'PA CC.1.2.2.I, CC.1.3.2.H: Compare and contrast the most important points of two texts on the same topic, or two versions of the same story.', 14, '2027-04-21', 'us-pa'),
  ('pa.g3.ela.questions-and-inferences', 'ela', 3, 'Answer questions and make inferences', 'Reading Literature', 'PA CC.1.3.3.B, CC.1.2.3.B: Ask and answer questions about a text and make inferences, referring to the text to support answers.', 0, '2026-09-02', 'us-pa'),
  ('pa.g3.ela.prefixes-suffixes', 'ela', 3, 'Common prefixes and suffixes', 'Foundational Skills', 'PA CC.1.1.3.D: Identify and know the meaning of the most common prefixes and derivational suffixes, and decode multisyllable words.', 1, '2026-09-09', 'us-pa'),
  ('pa.g3.ela.main-idea-key-details', 'ela', 3, 'Main idea and key details', 'Reading Informational Text', 'PA CC.1.2.3.A: Determine the main idea of a text, recount key details, and explain how they support the main idea.', 2, '2026-09-23', 'us-pa'),
  ('pa.g3.ela.story-central-message', 'ela', 3, 'Central message, lesson or moral', 'Reading Literature', 'PA CC.1.3.3.A: Determine the central message, lesson, or moral of a story and explain how the text conveys it.', 3, '2026-10-07', 'us-pa'),
  ('pa.g3.ela.nouns-verbs-adjectives', 'ela', 3, 'Nouns, verbs and adjectives', 'Conventions', 'PA CC.1.4.3.F, CC.1.4.3.L: Use grade-level grammar: identify nouns, verbs, adjectives and adverbs and how each works in a sentence.', 4, '2026-10-21', 'us-pa'),
  ('pa.g3.ela.context-clues', 'ela', 3, 'Context clues for unknown words', 'Vocabulary', 'PA CC.1.2.3.K, CC.1.3.3.I: Determine or clarify the meaning of unknown and multiple-meaning words using context clues and other strategies.', 5, '2026-11-04', 'us-pa'),
  ('pa.g3.ela.characters-actions', 'ela', 3, 'Characters and their actions', 'Reading Literature', 'PA CC.1.3.3.C: Describe characters in a story and explain how their actions contribute to the sequence of events.', 6, '2026-11-18', 'us-pa'),
  ('pa.g3.ela.text-features', 'ela', 3, 'Using text features', 'Reading Informational Text', 'PA CC.1.2.3.E, CC.1.2.3.G: Use text features and search tools to locate and interpret information and understand a text.', 7, '2026-12-02', 'us-pa'),
  ('pa.g3.ela.literal-nonliteral', 'ela', 3, 'Literal and nonliteral meaning', 'Vocabulary', 'PA CC.1.3.3.F, CC.1.2.3.F: Determine the meaning of words and phrases in a text, telling literal from nonliteral meaning and shades of meaning.', 8, '2026-12-16', 'us-pa'),
  ('pa.g3.ela.sentence-punctuation', 'ela', 3, 'Sentence types and end punctuation', 'Conventions', 'PA CC.1.4.3.L, CC.1.4.3.R: Use grade-level conventions: recognize statements, questions, commands and exclamations, and use capitals and end punctuation.', 9, '2027-01-13', 'us-pa'),
  ('pa.g3.ela.sequence-cause-effect', 'ela', 3, 'Sequence and cause and effect', 'Reading Informational Text', 'PA CC.1.2.3.C: Explain how events, ideas, or steps in a text are connected, using words for time, sequence, and cause/effect.', 10, '2027-01-27', 'us-pa'),
  ('pa.g3.ela.author-point-of-view', 'ela', 3, 'Author''s point of view', 'Reading Informational Text', 'PA CC.1.2.3.D, CC.1.3.3.D: Explain the point of view of the author of a text.', 11, '2027-02-10', 'us-pa'),
  ('pa.g3.ela.chapter-scene-stanza', 'ela', 3, 'Chapters, scenes and stanzas', 'Reading Literature', 'PA CC.1.3.3.E: Refer to parts of texts using terms such as chapter, scene, and stanza and describe how each part builds on earlier ones.', 12, '2027-03-03', 'us-pa'),
  ('pa.g3.ela.compare-two-texts', 'ela', 3, 'Compare two texts on one topic', 'Reading Informational Text', 'PA CC.1.2.3.I: Compare and contrast the most important points and key details in two texts on the same topic.', 13, '2027-03-24', 'us-pa'),
  ('pa.g3.ela.compare-stories-same-author', 'ela', 3, 'Compare stories by the same author', 'Reading Literature', 'PA CC.1.3.3.H: Compare and contrast the themes, settings, and plots of stories by the same author about similar characters.', 14, '2027-04-21', 'us-pa'),
  ('pa.g4.ela.details-and-inferences', 'ela', 4, 'Details, examples and inferences', 'Reading Literature', 'PA CC.1.3.4.B, CC.1.2.4.B: Refer to details and examples in a text to support what it says explicitly and to make inferences.', 0, '2026-09-02', 'us-pa'),
  ('pa.g4.ela.main-idea-summary', 'ela', 4, 'Main idea and summary', 'Reading Informational Text', 'PA CC.1.2.4.A: Determine the main idea of a text, explain how key details support it, and summarize the text.', 1, '2026-09-16', 'us-pa'),
  ('pa.g4.ela.story-theme', 'ela', 4, 'Theme of a story', 'Reading Literature', 'PA CC.1.3.4.A: Determine a theme of a story from details in the text and summarize the text.', 2, '2026-09-30', 'us-pa'),
  ('pa.g4.ela.context-clues-word-parts', 'ela', 4, 'Context clues and word parts', 'Vocabulary', 'PA CC.1.2.4.K, CC.1.3.4.I, CC.1.1.4.D: Determine the meaning of unknown and multiple-meaning words using context, prefixes, suffixes and roots.', 3, '2026-10-14', 'us-pa'),
  ('pa.g4.ela.verb-tenses-pronouns', 'ela', 4, 'Verb tenses and pronouns', 'Conventions', 'PA CC.1.4.4.F, CC.1.4.4.L: Use grade-level grammar: progressive verb tenses, helping verbs, and relative pronouns (who, which, that).', 4, '2026-10-28', 'us-pa'),
  ('pa.g4.ela.character-setting-event', 'ela', 4, 'Describe a character, setting or event', 'Reading Literature', 'PA CC.1.3.4.C: Describe in depth a character, setting, or event in a story or drama, drawing on specific details in the text.', 5, '2026-11-10', 'us-pa'),
  ('pa.g4.ela.figurative-language', 'ela', 4, 'Similes, metaphors and idioms', 'Vocabulary', 'PA CC.1.3.4.F, CC.1.2.4.F: Determine the meaning of words and phrases in a text, including figurative language such as similes, metaphors and idioms.', 6, '2026-11-24', 'us-pa'),
  ('pa.g4.ela.text-structure', 'ela', 4, 'Text structure: cause, compare, problem', 'Reading Informational Text', 'PA CC.1.2.4.E: Use text structure (chronology, comparison, cause/effect, problem/solution) to interpret information.', 7, '2026-12-08', 'us-pa'),
  ('pa.g4.ela.precise-words', 'ela', 4, 'Precise words for actions and feelings', 'Vocabulary', 'PA CC.1.3.4.J, CC.1.2.4.J: Use grade-level words and phrases accurately, including those that signal precise actions, emotions, or states of being.', 8, '2027-01-05', 'us-pa'),
  ('pa.g4.ela.commas-quotation-marks', 'ela', 4, 'Commas and quotation marks', 'Conventions', 'PA CC.1.4.4.L, CC.1.4.4.R: Use grade-level punctuation: commas in compound sentences and quotation marks for dialogue and direct quotes.', 9, '2027-01-19', 'us-pa'),
  ('pa.g4.ela.first-third-person', 'ela', 4, 'First- and third-person point of view', 'Reading Literature', 'PA CC.1.3.4.D, CC.1.2.4.D: Compare and contrast an event or topic told from two different points of view, such as first and third person.', 10, '2027-02-02', 'us-pa'),
  ('pa.g4.ela.poems-drama-prose', 'ela', 4, 'Poems, drama and prose', 'Reading Literature', 'PA CC.1.3.4.E: Explain major differences between poems, drama, and prose and refer to their structural elements (verse, cast, dialogue).', 11, '2027-02-23', 'us-pa'),
  ('pa.g4.ela.reasons-and-evidence', 'ela', 4, 'How authors use reasons and evidence', 'Reading Informational Text', 'PA CC.1.2.4.H: Explain how an author uses reasons and evidence to support particular points in a text.', 12, '2027-03-16', 'us-pa'),
  ('pa.g4.ela.confused-words-sentences', 'ela', 4, 'Confused words and complete sentences', 'Conventions', 'PA CC.1.4.4.F, CC.1.4.4.R: Use grade-level conventions: choose commonly confused words (to/too/two, their/there) and fix fragments and run-ons.', 13, '2027-04-06', 'us-pa'),
  ('pa.g4.ela.compare-themes-cultures', 'ela', 4, 'Compare themes across cultures', 'Reading Literature', 'PA CC.1.3.4.H: Compare and contrast similar themes, topics, and patterns of events in stories, including texts from different cultures.', 14, '2027-04-27', 'us-pa'),
  ('pa.g7.ela.textual-evidence', 'ela', 7, 'Textual evidence and inferences', 'Reading Literature', 'PA CC.1.3.7.B, CC.1.2.7.B: Cite several pieces of textual evidence to support what a text says explicitly and the inferences or conclusions drawn from it.', 0, '2026-09-02', 'us-pa'),
  ('pa.g7.ela.theme-objective-summary', 'ela', 7, 'Theme and objective summary', 'Reading Literature', 'PA CC.1.3.7.A: Determine a theme or central idea of a text, analyze its development, and give an objective summary.', 1, '2026-09-16', 'us-pa'),
  ('pa.g7.ela.central-ideas', 'ela', 7, 'Central ideas of informational text', 'Reading Informational Text', 'PA CC.1.2.7.A: Determine two or more central ideas in a text, analyze their development, and provide an objective summary.', 2, '2026-09-30', 'us-pa'),
  ('pa.g7.ela.roots-affixes-context', 'ela', 7, 'Greek and Latin roots and context clues', 'Vocabulary', 'PA CC.1.2.7.K, CC.1.3.7.I: Determine the meaning of unknown and multiple-meaning words using context, Greek or Latin roots and affixes, and other strategies.', 3, '2026-10-14', 'us-pa'),
  ('pa.g7.ela.phrases-clauses', 'ela', 7, 'Phrases and clauses', 'Conventions', 'PA CC.1.4.7.F, CC.1.4.7.L: Use grade-level grammar: identify phrases and clauses and explain their function in a sentence.', 4, '2026-10-28', 'us-pa'),
  ('pa.g7.ela.setting-shapes-plot', 'ela', 7, 'How setting shapes characters and plot', 'Reading Literature', 'PA CC.1.3.7.C: Analyze how elements of a story or drama interact and how setting shapes the characters or plot.', 5, '2026-11-10', 'us-pa'),
  ('pa.g7.ela.figurative-connotative', 'ela', 7, 'Figurative and connotative meanings', 'Vocabulary', 'PA CC.1.3.7.F, CC.1.2.7.F: Determine the meaning of words and phrases as used in a text, including figurative, connotative, and technical meanings.', 6, '2026-11-24', 'us-pa'),
  ('pa.g7.ela.author-purpose-viewpoint', 'ela', 7, 'Author''s point of view and purpose', 'Reading Informational Text', 'PA CC.1.2.7.D: Determine an author''s point of view or purpose and analyze how the author separates that position from others''.', 7, '2026-12-08', 'us-pa'),
  ('pa.g7.ela.sentence-structures', 'ela', 7, 'Simple, compound and complex sentences', 'Conventions', 'PA CC.1.4.7.L, CC.1.4.7.R: Use grade-level grammar: choose among simple, compound, complex and compound-complex sentences to show how ideas relate.', 8, '2027-01-05', 'us-pa'),
  ('pa.g7.ela.characters-narrators-pov', 'ela', 7, 'Points of view of characters and narrators', 'Reading Literature', 'PA CC.1.3.7.D: Analyze how an author develops and contrasts the points of view of different characters or narrators.', 9, '2027-01-26', 'us-pa'),
  ('pa.g7.ela.individuals-events-ideas', 'ela', 7, 'How people, events and ideas interact', 'Reading Informational Text', 'PA CC.1.2.7.C: Analyze the interactions between individuals, events, and ideas in an informational text.', 10, '2027-02-09', 'us-pa'),
  ('pa.g7.ela.structure-and-meaning', 'ela', 7, 'How structure shapes meaning', 'Reading Literature', 'PA CC.1.3.7.E: Analyze how the structure or form of a text (such as a poem or drama) contributes to its meaning.', 11, '2027-03-02', 'us-pa'),
  ('pa.g7.ela.evaluate-argument', 'ela', 7, 'Evaluate an argument and its evidence', 'Reading Informational Text', 'PA CC.1.2.7.H: Evaluate an author''s argument, reasoning, and claims for soundness and the relevance of the evidence.', 12, '2027-03-16', 'us-pa'),
  ('pa.g7.ela.commas-coordinate-adjectives', 'ela', 7, 'Commas, including coordinate adjectives', 'Conventions', 'PA CC.1.4.7.F, CC.1.4.7.R: Use grade-level punctuation: commas to separate coordinate adjectives, after introductory elements, and with clauses.', 13, '2027-04-06', 'us-pa'),
  ('pa.g7.ela.precise-concise-language', 'ela', 7, 'Precise, concise language', 'Conventions', 'PA CC.1.4.7.Q, CC.1.4.7.K: Choose language that expresses ideas precisely and concisely, recognizing and eliminating wordiness and redundancy.', 14, '2027-04-27', 'us-pa'),
  ('pa.g2.fen.material-properties', 'fen', 2, 'Sorting materials by their properties', 'Physical Science', 'PA 3.2.2.A: Materials can be described and sorted by properties we can observe, such as color, texture, hardness and whether they bend or float.', 0, '2026-09-02', 'us-pa'),
  ('pa.g2.fen.best-material-for-the-job', 'fen', 2, 'Choosing the best material for a job', 'Physical Science', 'PA 3.2.2.B: Different materials have different properties, so some are better suited than others for a purpose, like waterproof boots or a strong bridge.', 1, '2026-09-16', 'us-pa'),
  ('pa.g2.fen.pieces-make-new-objects', 'fen', 2, 'Taking apart and building new objects', 'Physical Science', 'PA 3.2.2.C: An object made of a small set of pieces can be taken apart and the same pieces can be put together to make a new, different object.', 2, '2026-09-30', 'us-pa'),
  ('pa.g2.fen.heating-and-cooling', 'fen', 2, 'Heating and cooling: can it change back?', 'Physical Science', 'PA 3.2.2.D: Heating or cooling can change materials. Some changes can be reversed, like melting ice, and some cannot, like cooking an egg or burning paper.', 3, '2026-10-14', 'us-pa'),
  ('pa.g2.fen.what-plants-need', 'fen', 2, 'What plants need to grow', 'Life Science', 'PA 3.1.2.A: Plants need sunlight and water to grow and stay healthy.', 4, '2026-10-28', 'us-pa'),
  ('pa.g2.fen.seeds-and-pollination', 'fen', 2, 'How animals spread seeds and pollen', 'Life Science', 'PA 3.1.2.B: Many plants depend on animals to move their seeds to new places and to carry pollen from flower to flower so new seeds can form.', 5, '2026-11-18', 'us-pa'),
  ('pa.g2.fen.habitats', 'fen', 2, 'Life in different habitats', 'Life Science', 'PA 3.1.2.C: Different habitats, such as forests, ponds, deserts and oceans, are home to different kinds of plants and animals.', 6, '2026-12-09', 'us-pa'),
  ('pa.g2.fen.land-and-water-shapes', 'fen', 2, 'Kinds of land and bodies of water', 'Earth and Space Science', 'PA 3.3.2.C: Earth has many shapes and kinds of land, like mountains, hills, valleys and plains, and bodies of water, like oceans, lakes, rivers and ponds.', 7, '2027-01-13', 'us-pa'),
  ('pa.g2.fen.water-on-earth', 'fen', 2, 'Where water is found on Earth', 'Earth and Space Science', 'PA 3.3.2.D: Water is found in oceans, rivers, lakes, ponds and underground, and as ice in glaciers. Water on Earth can be solid or liquid.', 8, '2027-01-27', 'us-pa'),
  ('pa.g2.fen.fast-and-slow-earth-changes', 'fen', 2, 'Earth changes: fast and slow', 'Earth and Space Science', 'PA 3.3.2.A: Some Earth events happen quickly, like volcanoes, earthquakes and landslides; others happen slowly, like rivers wearing away rock over many years.', 9, '2027-02-17', 'us-pa'),
  ('pa.g2.fen.stopping-wind-and-water-erosion', 'fen', 2, 'Protecting land from wind and water', 'Earth and Space Science', 'PA 3.3.2.B: Wind and water can change the shape of land. People slow this down with things like plants, walls, dams and windbreaks.', 10, '2027-03-10', 'us-pa'),
  ('pa.g2.fen.natural-resources', 'fen', 2, 'Natural resources we use', 'Environment', 'PA 3.4.K-2.A: Natural resources such as water, wood, soil, rocks and plants are taken from nature and used by people for food, shelter and things we need.', 11, '2027-04-07', 'us-pa'),
  ('pa.g2.fen.reduce-reuse-recycle', 'fen', 2, 'Reduce, reuse, recycle', 'Environment', 'PA 3.5.K-2.D: We can save resources and make less trash by reducing what we use, reusing things and recycling materials like paper, glass, metal and plastic.', 12, '2027-04-28', 'us-pa'),
  ('pa.g3.fen.patterns-of-motion', 'fen', 3, 'Patterns of motion', 'Physical Science', 'PA 3.2.3.A: When an object moves in a repeating pattern, like a swing or a rolling ball, the pattern can be used to predict how it will move next.', 0, '2026-09-02', 'us-pa'),
  ('pa.g3.fen.balanced-and-unbalanced-forces', 'fen', 3, 'Pushes, pulls and balanced forces', 'Physical Science', 'PA 3.2.3.A: Forces are pushes and pulls. Balanced forces do not change an object''s motion; unbalanced forces make it start, stop, speed up or change direction.', 1, '2026-09-16', 'us-pa'),
  ('pa.g3.fen.magnets-and-static-electricity', 'fen', 3, 'Magnets and static electricity', 'Physical Science', 'PA 3.2.3.C, 3.2.3.D: Magnets and electrically charged objects can push or pull each other without touching. Magnets attract iron; like poles repel and opposite poles attract.', 2, '2026-09-30', 'us-pa'),
  ('pa.g3.fen.weather-and-seasons', 'fen', 3, 'Weather in each season', 'Earth and Space Science', 'PA 3.3.3.A: Weather is described by temperature, rain or snow, wind and clouds. Each season has typical weather, like hot summers and cold, snowy winters.', 3, '2026-10-14', 'us-pa'),
  ('pa.g3.fen.climates-of-the-world', 'fen', 3, 'Climates around the world', 'Earth and Space Science', 'PA 3.3.3.B: Climate is the usual weather of a region over many years. Different regions have different climates, such as hot and dry deserts or cold polar areas.', 4, '2026-10-28', 'us-pa'),
  ('pa.g3.fen.weather-hazards', 'fen', 3, 'Staying safe from weather hazards', 'Earth and Space Science', 'PA 3.3.3.C: Weather hazards include floods, storms, tornadoes and blizzards. People reduce their harm with things like levees, storm shelters and warnings.', 5, '2026-11-10', 'us-pa'),
  ('pa.g3.fen.life-cycles', 'fen', 3, 'Life cycles of plants and animals', 'Life Science', 'PA 3.1.3.A: Plants and animals have different life cycles, but all share birth, growth, reproduction and death.', 6, '2026-12-02', 'us-pa'),
  ('pa.g3.fen.inherited-traits', 'fen', 3, 'Traits passed from parents', 'Life Science', 'PA 3.1.3.C: Plants and animals inherit traits from their parents, and individuals of the same kind still vary in their traits.', 7, '2026-12-16', 'us-pa'),
  ('pa.g3.fen.traits-and-environment', 'fen', 3, 'How the environment affects traits', 'Life Science', 'PA 3.1.3.D: The environment can change traits: a plant with little water or light grows smaller, and an animal with too little food may be weaker.', 8, '2027-01-13', 'us-pa'),
  ('pa.g3.fen.helpful-differences', 'fen', 3, 'Differences that help survival', 'Life Science', 'PA 3.1.3.F: Differences among individuals of the same species, like better camouflage or longer thorns, can help some survive, find mates and have young.', 9, '2027-01-27', 'us-pa'),
  ('pa.g3.fen.animal-groups', 'fen', 3, 'Animals living in groups', 'Life Science', 'PA 3.1.3.B: Some animals live in groups, like herds, packs, schools and colonies, which help members find food, defend themselves and cope with change.', 10, '2027-02-10', 'us-pa'),
  ('pa.g3.fen.surviving-in-a-habitat', 'fen', 3, 'Who survives in a habitat', 'Life Science', 'PA 3.1.3.G: In a given habitat some organisms survive well, some survive less well and some cannot survive at all, depending on whether their needs are met.', 11, '2027-03-03', 'us-pa'),
  ('pa.g3.fen.fossils', 'fen', 3, 'Fossils and life long ago', 'Life Science', 'PA 3.1.3.E: Fossils show what kinds of organisms lived long ago and what their environments were like, such as a fish fossil showing land was once under water.', 12, '2027-03-24', 'us-pa'),
  ('pa.g3.fen.when-environments-change', 'fen', 3, 'When environments change', 'Life Science', 'PA 3.1.3.H: When an environment changes, some plants and animals move, some survive and some die; people can help, for example by protecting habitats.', 13, '2027-04-14', 'us-pa'),
  ('pa.g3.fen.living-things-and-environment', 'fen', 3, 'Living things and their environment', 'Environment', 'PA 3.4.3-5.A: Living things, including humans, change the environment they live in, and the environment in turn affects them.', 14, '2027-05-05', 'us-pa'),
  ('pa.g4.fen.speed-and-energy', 'fen', 4, 'Speed and energy', 'Physical Science', 'PA 3.2.4.A: The faster an object moves, the more energy it has.', 0, '2026-09-02', 'us-pa'),
  ('pa.g4.fen.energy-transfer', 'fen', 4, 'How energy moves from place to place', 'Physical Science', 'PA 3.2.4.B: Energy can be moved from place to place by sound, light, heat and electric currents.', 1, '2026-09-16', 'us-pa'),
  ('pa.g4.fen.collisions', 'fen', 4, 'Energy in collisions', 'Physical Science', 'PA 3.2.4.C: When objects collide, energy is transferred between them and some of it changes form, often into sound and heat; the objects'' motion changes.', 2, '2026-09-30', 'us-pa'),
  ('pa.g4.fen.energy-changes-form', 'fen', 4, 'Energy changing from one form to another', 'Physical Science', 'PA 3.2.4.D: Devices change energy from one form to another, like a light bulb turning electricity into light or a battery storing energy that becomes motion.', 3, '2026-10-14', 'us-pa'),
  ('pa.g4.fen.waves', 'fen', 4, 'Waves: amplitude and wavelength', 'Physical Science', 'PA 3.2.4.E: Waves are regular patterns of motion. Amplitude is the height of a wave and wavelength is the distance between peaks; waves can make objects move.', 4, '2026-10-28', 'us-pa'),
  ('pa.g4.fen.light-and-seeing', 'fen', 4, 'Light and how we see', 'Physical Science', 'PA 3.2.4.F: We see objects when light reflects off them and enters our eyes.', 5, '2026-11-09', 'us-pa'),
  ('pa.g4.fen.sending-information-with-patterns', 'fen', 4, 'Sending messages with patterns', 'Physical Science', 'PA 3.2.4.G: Information can be sent over distance using patterns, such as Morse code, drum beats, flashing lights or the 1s and 0s computers use.', 6, '2026-11-18', 'us-pa'),
  ('pa.g4.fen.structures-for-survival', 'fen', 4, 'Plant and animal parts that help survival', 'Life Science', 'PA 3.1.4.A: Plants and animals have internal and external structures, like roots, thorns, hearts and shells, that help them survive, grow, behave and reproduce.', 7, '2026-12-02', 'us-pa'),
  ('pa.g4.fen.senses-and-the-brain', 'fen', 4, 'Senses and the brain', 'Life Science', 'PA 3.1.4.B: Animals take in information through their senses, process it in the brain and respond in different ways.', 8, '2027-01-13', 'us-pa'),
  ('pa.g4.fen.rock-layers-and-fossils', 'fen', 4, 'Rock layers and fossils', 'Earth and Space Science', 'PA 3.3.4.A: Patterns in rock layers and the fossils in them show how a landscape changed over time; lower layers are usually older than upper layers.', 9, '2027-02-03', 'us-pa'),
  ('pa.g4.fen.weathering-and-erosion', 'fen', 4, 'Weathering and erosion', 'Earth and Space Science', 'PA 3.3.4.B: Weathering breaks rock into smaller pieces; erosion moves them. Water, ice, wind and plants cause both.', 10, '2027-02-24', 'us-pa'),
  ('pa.g4.fen.earths-features-on-maps', 'fen', 4, 'Patterns of Earth''s features on maps', 'Earth and Space Science', 'PA 3.3.4.C: Maps show patterns in Earth''s features: mountains, volcanoes and earthquakes often occur in belts, many along the edges of continents.', 11, '2027-03-10', 'us-pa'),
  ('pa.g4.fen.natural-hazards', 'fen', 4, 'Natural hazards and staying safe', 'Earth and Space Science', 'PA 3.3.4.E: Natural Earth processes like earthquakes, floods, volcanoes and tsunamis can harm people; their impact is reduced by warnings and stronger buildings.', 12, '2027-03-31', 'us-pa'),
  ('pa.g4.fen.energy-resources', 'fen', 4, 'Energy resources: renewable or not', 'Earth and Space Science', 'PA 3.3.4.D, 3.5.3-5.F: Energy and fuels come from natural resources. Renewable ones (sun, wind, water) are replaced naturally; nonrenewable ones (coal, oil, gas) run out.', 13, '2027-04-21', 'us-pa'),
  ('pa.g4.fen.people-and-the-environment', 'fen', 4, 'How people depend on and change nature', 'Environment', 'PA 3.4.3-5.F: People depend on the environment for food, water and materials, and change it by building, farming and polluting, which can harm or protect it.', 14, '2027-05-12', 'us-pa'),
  ('pa.g7.fen.atoms-and-molecules', 'fen', 7, 'Atoms and molecules', 'Physical Science', 'PA 3.2.6-8.A: All matter is made of atoms. Atoms join to form molecules, like water (H2O), or large repeating structures, like crystals of salt.', 0, '2026-09-02', 'us-pa'),
  ('pa.g7.fen.cells', 'fen', 7, 'Cells and their parts', 'Life Science', 'PA 3.1.6-8.A, 3.1.6-8.B: All living things are made of one or many cells. Cell parts, like the nucleus, membrane, mitochondria and chloroplasts, each do a job for the cell.', 1, '2026-09-16', 'us-pa'),
  ('pa.g7.fen.body-systems', 'fen', 7, 'Body systems working together', 'Life Science', 'PA 3.1.6-8.C: The body is a system of subsystems: cells form tissues, tissues form organs, and organs form systems like the digestive and circulatory systems.', 2, '2026-09-30', 'us-pa'),
  ('pa.g7.fen.senses-and-nervous-system', 'fen', 7, 'Senses and the nervous system', 'Life Science', 'PA 3.1.6-8.H: Sensory receptors respond to stimuli and send messages through nerves to the brain, which triggers a quick response or stores them as memories.', 3, '2026-10-14', 'us-pa'),
  ('pa.g7.fen.photosynthesis', 'fen', 7, 'Photosynthesis', 'Life Science', 'PA 3.1.6-8.F: In photosynthesis, plants use light energy to make sugar from carbon dioxide and water, releasing oxygen; this brings matter and energy into food webs.', 4, '2026-10-28', 'us-pa'),
  ('pa.g7.fen.food-and-cellular-respiration', 'fen', 7, 'Food, energy and cellular respiration', 'Life Science', 'PA 3.1.6-8.G: Food molecules are rearranged in chemical reactions; cellular respiration releases their energy, and the matter is used to build and grow.', 5, '2026-11-09', 'us-pa'),
  ('pa.g7.fen.sexual-and-asexual-reproduction', 'fen', 7, 'Sexual and asexual reproduction', 'Life Science', 'PA 3.1.6-8.N, 3.1.6-8.D: Asexual reproduction makes offspring with identical genetic information; sexual reproduction combines genes from two parents, giving variation.', 6, '2026-11-18', 'us-pa'),
  ('pa.g7.fen.genes-and-mutations', 'fen', 7, 'Genes, chromosomes and mutations', 'Life Science', 'PA 3.1.6-8.M, 3.1.6-8.E: Genes on chromosomes code for proteins that shape traits. Mutations change genes and can be harmful, helpful or neutral; environment also affects growth.', 7, '2026-12-02', 'us-pa'),
  ('pa.g7.fen.natural-selection', 'fen', 7, 'Natural selection', 'Life Science', 'PA 3.1.6-8.S, 3.1.6-8.T: Individuals with helpful genetic variations are more likely to survive and reproduce, so over generations those traits become more common.', 8, '2027-01-06', 'us-pa'),
  ('pa.g7.fen.fossil-record-and-evolution', 'fen', 7, 'Fossil record and evolution', 'Life Science', 'PA 3.1.6-8.O, 3.1.6-8.P: The fossil record shows life forms that existed, went extinct and changed over time; similar body structures point to shared ancestors.', 9, '2027-01-20', 'us-pa'),
  ('pa.g7.fen.ecosystem-interactions', 'fen', 7, 'Interactions in ecosystems', 'Life Science', 'PA 3.1.6-8.I, 3.1.6-8.J: Organisms compete for limited resources and interact as predator and prey or as partners; the supply of resources limits population size.', 10, '2027-02-03', 'us-pa'),
  ('pa.g7.fen.food-webs-and-matter-cycles', 'fen', 7, 'Food webs, energy flow and matter cycles', 'Life Science', 'PA 3.1.6-8.K: Producers, consumers and decomposers cycle matter between living and nonliving parts of an ecosystem, while energy flows through food webs.', 11, '2027-02-24', 'us-pa'),
  ('pa.g7.fen.changing-ecosystems', 'fen', 7, 'Changing ecosystems and biodiversity', 'Life Science', 'PA 3.1.6-8.L, 3.1.6-8.U: Changes to physical or living parts of an ecosystem affect its populations; biodiversity helps keep ecosystem services like clean water and pollination.', 12, '2027-03-10', 'us-pa'),
  ('pa.g7.fen.water-cycle', 'fen', 7, 'The water cycle', 'Earth and Space Science', 'PA 3.3.6-8.H: Water cycles through evaporation, condensation, precipitation and runoff, driven by energy from the sun and by gravity.', 13, '2027-03-31', 'us-pa'),
  ('pa.g7.fen.watersheds-and-wetlands', 'fen', 7, 'Watersheds and wetlands', 'Environment', 'PA 3.4.6-8.C: A watershed is land that drains into a common body of water. Wetlands filter water, reduce flooding and provide habitat for many species.', 14, '2027-04-21', 'us-pa'),
  ('pa.g2.sosyal.rules-at-school', 'sosyal', 2, 'Why we have rules', 'Civics and Government', 'PA 5.1.2.A, 5.1.2.B, 5.3.2.F: Know why we have rules in the classroom and school, and what can happen when someone does not follow them.', 0, '2026-09-02', 'us-pa'),
  ('pa.g2.sosyal.maps-and-directions', 'sosyal', 2, 'Maps, map keys and directions', 'Geography', 'PA 7.1.2.A: Use basic geographic tools: know what maps and globes show, what a map key is for, and the four cardinal directions (north, south, east, west).', 1, '2026-09-16', 'us-pa'),
  ('pa.g2.sosyal.needs-and-wants', 'sosyal', 2, 'Needs and wants', 'Economics', 'PA 6.1.2.A, 6.1.2.B, 6.1.2.C: Tell needs from wants, know that resources are limited (scarcity), and make choices based on needs versus wants.', 2, '2026-09-30', 'us-pa'),
  ('pa.g2.sosyal.past-present-timelines', 'sosyal', 2, 'Past, present and timelines', 'History', 'PA 8.1.2.A, 8.1.2.C: Read simple timelines, put events in order, and know that sources can tell us about the past.', 3, '2026-10-14', 'us-pa'),
  ('pa.g2.sosyal.responsible-citizen', 'sosyal', 2, 'Being a responsible citizen', 'Civics and Government', 'PA 5.2.2.A, 5.2.2.C, 5.2.2.D, 5.2.2.B: Know our responsibilities at home, at school and in the community, how to be a responsible member of a community, and ways to solve a problem.', 4, '2026-10-28', 'us-pa'),
  ('pa.g2.sosyal.landmarks-and-places', 'sosyal', 2, 'Finding places with landmarks', 'Geography', 'PA 7.1.2.B: Locate places we often visit by using landmarks and simple directions, like near, far, left and right.', 5, '2026-11-10', 'us-pa'),
  ('pa.g2.sosyal.goods-and-services', 'sosyal', 2, 'Goods, services and trade', 'Economics', 'PA 6.2.2.A, 6.4.2.A, 6.4.2.B: Identify goods, services, consumers and producers in the community, know that workers specialize in jobs, and explain why people trade.', 6, '2026-12-01', 'us-pa'),
  ('pa.g2.sosyal.local-history', 'sosyal', 2, 'Our community''s history', 'History', 'PA 8.2.2.A, 8.2.2.B, 8.2.2.C: Identify important people, buildings and monuments of local and Pennsylvania history, and how work and community life have changed over time.', 7, '2026-12-15', 'us-pa'),
  ('pa.g2.sosyal.community-leaders', 'sosyal', 2, 'Community leaders and elections', 'Civics and Government', 'PA 5.3.2.C, 5.3.2.D, 5.3.2.E: Identify services our community provides, people with authority at school and in the community, and the purpose of elections.', 8, '2027-01-12', 'us-pa'),
  ('pa.g2.sosyal.land-and-water', 'sosyal', 2, 'Land, water, continents and oceans', 'Geography', 'PA 7.2.2.A, 7.2.2.B: Identify physical features such as mountains, plains, rivers, lakes, continents and oceans, and how weather and water change the land.', 9, '2027-01-26', 'us-pa'),
  ('pa.g2.sosyal.symbols-and-holidays', 'sosyal', 2, 'American symbols and holidays', 'Civics and Government', 'PA 5.1.2.F: Identify state symbols, national symbols such as the flag and the Liberty Bell, and national holidays.', 10, '2027-02-16', 'us-pa'),
  ('pa.g2.sosyal.earning-and-saving', 'sosyal', 2, 'Earning, spending and saving', 'Economics', 'PA 6.5.2.A, 6.5.2.G, 6.3.2.C: Explain how money adults earn pays for needs and wants, how long saving takes for a purchase, and what taxes are and who pays them.', 11, '2027-03-02', 'us-pa'),
  ('pa.g2.sosyal.environment-and-people', 'sosyal', 2, 'How nature changes our lives', 'Geography', 'PA 7.4.2.A, 7.4.2.B: Identify physical systems like weather, water and soil, and how changes in the environment affect people.', 12, '2027-03-23', 'us-pa'),
  ('pa.g2.sosyal.celebrations-and-remembrances', 'sosyal', 2, 'Celebrations and remembrances', 'History', 'PA 8.4.2.A, 8.4.2.C, 8.3.2.B: Explain why cultures hold commemorations and remembrances, and identify American artifacts that matter in our history.', 13, '2027-04-13', 'us-pa'),
  ('pa.g3.sosyal.rules-and-laws', 'sosyal', 3, 'Rules, laws and government', 'Civics and Government', 'PA 5.1.3.A, 5.1.3.B: Explain the purposes of rules, laws and consequences, and the rules and laws for the classroom, school and community.', 0, '2026-09-02', 'us-pa'),
  ('pa.g3.sosyal.geographic-tools', 'sosyal', 3, 'Maps, globes and directions', 'Geography', 'PA 7.1.3.A: Know how maps, globes, map keys, compass roses and scales help us learn about people, places and environments.', 1, '2026-09-16', 'us-pa'),
  ('pa.g3.sosyal.scarcity-and-resources', 'sosyal', 3, 'Scarcity, resources and choices', 'Economics', 'PA 6.1.3.A, 6.1.3.B, 6.1.3.C, 6.1.3.D: Define scarcity, tell needs from wants, name natural, human and capital resources, and explain what is given up when making a choice.', 2, '2026-09-30', 'us-pa'),
  ('pa.g3.sosyal.past-present-future', 'sosyal', 3, 'Past, present, future and sources', 'History', 'PA 8.1.3.A, 8.1.3.B: Tell past, present and future apart using timelines, and identify fact, opinion, points of view and primary sources about events.', 3, '2026-10-14', 'us-pa'),
  ('pa.g3.sosyal.rights-and-responsibilities', 'sosyal', 3, 'Rights, responsibilities and conflict', 'Civics and Government', 'PA 5.2.3.A, 5.2.3.B, 5.2.3.D: Identify personal rights and responsibilities, sources of conflict and ways to resolve them, and how citizens take part in the community.', 4, '2026-10-28', 'us-pa'),
  ('pa.g3.sosyal.goods-services-competition', 'sosyal', 3, 'Goods, services and local businesses', 'Economics', 'PA 6.2.3.A, 6.2.3.B, 6.2.3.C, 6.2.3.E: Identify goods, services, consumers and producers, competing sellers, advertising, and the effect of local businesses opening and closing.', 5, '2026-11-10', 'us-pa'),
  ('pa.g3.sosyal.places-and-regions', 'sosyal', 3, 'Places, regions and landforms', 'Geography', 'PA 7.1.3.B, 7.2.3.A, 7.2.3.B: Identify places and regions by physical and human features, landforms and bodies of water, and processes like weather and erosion that shape them.', 6, '2026-12-01', 'us-pa'),
  ('pa.g3.sosyal.local-government', 'sosyal', 3, 'Branches of government and elections', 'Civics and Government', 'PA 5.3.3.A, 5.3.3.C, 5.3.3.D, 5.3.3.E: Identify the roles of the three branches of government, services of local government, positions of authority, and the purpose of elections.', 7, '2026-12-15', 'us-pa'),
  ('pa.g3.sosyal.pa-history', 'sosyal', 3, 'Pennsylvania people and places', 'History', 'PA 8.2.3.A, 8.2.3.B: Identify contributions of individuals and groups from Pennsylvania, and historic documents, artifacts and places important to Pennsylvania history.', 8, '2027-01-12', 'us-pa'),
  ('pa.g3.sosyal.jobs-and-trade', 'sosyal', 3, 'Jobs, specialization and trade', 'Economics', 'PA 6.5.3.A, 6.4.3.A, 6.4.3.B: Explain why people work, what specialization and division of labor are, and examples of trade, imports and exports.', 9, '2027-01-26', 'us-pa'),
  ('pa.g3.sosyal.symbols-and-documents', 'sosyal', 3, 'Symbols, holidays and documents', 'Civics and Government', 'PA 5.1.3.F, 5.1.3.D, 5.1.3.C: Identify state and national symbols and holidays, key ideas of the Declaration of Independence and Constitution, and ideals like liberty and justice.', 10, '2027-02-16', 'us-pa'),
  ('pa.g3.sosyal.people-and-places', 'sosyal', 3, 'People, communities and nature', 'Geography', 'PA 7.3.3.A, 7.4.3.A, 7.4.3.B: Describe communities by population, culture, settlement and work, and how nature affects people and people affect nature.', 11, '2027-03-09', 'us-pa'),
  ('pa.g3.sosyal.saving-banks-taxes', 'sosyal', 3, 'Saving, banks and taxes', 'Economics', 'PA 6.5.3.G, 6.5.3.H, 6.3.3.A, 6.3.3.C: Explain why people save, the role of banks, goods and services the government provides, and how taxes pay for them.', 12, '2027-03-30', 'us-pa'),
  ('pa.g3.sosyal.us-and-world-history', 'sosyal', 3, 'Our nation and world cultures', 'History', 'PA 8.3.3.A, 8.3.3.B, 8.4.3.A, 8.4.3.C: Identify contributions of people and groups in US history, important American documents and places, and elements of culture in world cultures.', 13, '2027-04-20', 'us-pa'),
  ('pa.g4.sosyal.map-tools', 'sosyal', 4, 'Map tools and directions', 'Geography', 'PA 7.1.4.A: Describe how maps, globes, map keys, scales, compass roses and grids are used to find and organize information about places.', 0, '2026-09-02', 'us-pa'),
  ('pa.g4.sosyal.pa-symbols', 'sosyal', 4, 'Pennsylvania and US symbols', 'Civics and Government', 'PA 5.1.4.F: Identify Pennsylvania state symbols, national symbols and national holidays and what they stand for.', 1, '2026-09-16', 'us-pa'),
  ('pa.g4.sosyal.pa-regions-landforms', 'sosyal', 4, 'Pennsylvania regions and landforms', 'Geography', 'PA 7.1.4.B, 7.2.4.A, 7.2.4.B: Describe and locate Pennsylvania''s regions, landforms, rivers and lakes, and the physical processes that shaped them.', 2, '2026-09-30', 'us-pa'),
  ('pa.g4.sosyal.pa-history-people', 'sosyal', 4, 'Famous Pennsylvanians', 'History', 'PA 8.2.4.A: Know important people and groups in Pennsylvania history and their social, political, cultural and economic contributions.', 3, '2026-10-14', 'us-pa'),
  ('pa.g4.sosyal.pa-resources-choices', 'sosyal', 4, 'Resources, needs and choices', 'Economics', 'PA 6.1.4.A, 6.1.4.B, 6.1.4.C, 6.1.4.D: Identify scarcity of resources in a community, tell needs from wants, know the role of producers, and what is given up when making a choice.', 4, '2026-10-28', 'us-pa'),
  ('pa.g4.sosyal.pa-historic-places', 'sosyal', 4, 'Historic places and documents', 'History', 'PA 8.2.4.B, 8.3.4.B: Know historical documents, artifacts and places critical to Pennsylvania and US history, such as Independence Hall and the Liberty Bell.', 5, '2026-11-10', 'us-pa'),
  ('pa.g4.sosyal.founding-documents', 'sosyal', 4, 'Founding documents and ideals', 'Civics and Government', 'PA 5.1.4.D, 5.1.4.C: Identify key ideas in the Declaration of Independence, US Constitution, Bill of Rights and Pennsylvania Constitution, and ideals like liberty and justice.', 6, '2026-12-01', 'us-pa'),
  ('pa.g4.sosyal.making-and-selling', 'sosyal', 4, 'Making, selling and trading', 'Economics', 'PA 6.2.4.A, 6.2.4.B, 6.2.4.D, 6.4.4.B: Explain how a product moves from production to consumption, how sellers compete, how buyers and sellers set prices, and why nations trade.', 7, '2026-12-15', 'us-pa'),
  ('pa.g4.sosyal.pa-government', 'sosyal', 4, 'Pennsylvania state government', 'Civics and Government', 'PA 5.3.4.A, 5.3.4.B, 5.3.4.D: Identify the roles of the three branches of government, how elected bodies make local and state laws, and leaders at each level.', 8, '2027-01-12', 'us-pa'),
  ('pa.g4.sosyal.pa-people-and-land', 'sosyal', 4, 'People and land in Pennsylvania', 'Geography', 'PA 7.3.4.A, 7.4.4.A, 7.4.4.B: Identify Pennsylvania''s population, culture, settlement and economic activities, and how land and people affect each other.', 9, '2027-01-26', 'us-pa'),
  ('pa.g4.sosyal.voting-and-citizens', 'sosyal', 4, 'Voting and good citizens', 'Civics and Government', 'PA 5.3.4.E, 5.2.4.A, 5.2.4.D, 5.2.4.C: Explain the voting process, rights and needs of ourselves and others, and how citizens and leaders serve the school, community and state.', 10, '2027-02-16', 'us-pa'),
  ('pa.g4.sosyal.public-goods-taxes', 'sosyal', 4, 'Public services and taxes', 'Economics', 'PA 6.3.4.A, 6.3.4.C, 6.3.4.B: Explain how government provides public goods and services, how tax money is used in the community, and government''s role in the economy.', 11, '2027-03-09', 'us-pa'),
  ('pa.g4.sosyal.pa-change-over-time', 'sosyal', 4, 'How Pennsylvania changed', 'History', 'PA 8.2.4.C, 8.2.4.D, 8.1.4.A: Explain how industry, technology, immigration and conflicts changed Pennsylvania, and how geography and climate influenced its history.', 12, '2027-03-30', 'us-pa'),
  ('pa.g4.sosyal.careers-saving-banks', 'sosyal', 4, 'Careers, saving and banks', 'Economics', 'PA 6.5.4.B, 6.5.4.G, 6.5.4.H: Identify requirements for different careers, compare ways people save, and the basic operation of banks.', 13, '2027-04-20', 'us-pa'),
  ('pa.g7.sosyal.historical-sources', 'sosyal', 7, 'Primary sources and chronology', 'History', 'PA 8.1.7.A, 8.1.7.B: Put events in sequential order with context, and use primary and secondary sources to analyze multiple points of view on events.', 0, '2026-09-02', 'us-pa'),
  ('pa.g7.sosyal.geographic-tools', 'sosyal', 7, 'Geographic tools and location', 'Geography', 'PA 7.1.7.A, 7.1.7.B: Explain how maps, globes, latitude and longitude are used, and locate places and regions by their physical and human features.', 1, '2026-09-16', 'us-pa'),
  ('pa.g7.sosyal.types-of-government', 'sosyal', 7, 'Types and principles of government', 'Civics and Government', 'PA 5.1.7.B, 5.3.7.J, 5.1.7.C: Identify types of government and how they make laws, and how liberty, democracy, justice and equality shape local, state and national government.', 2, '2026-09-30', 'us-pa'),
  ('pa.g7.sosyal.scarcity-and-incentives', 'sosyal', 7, 'Scarcity, opportunity cost, incentives', 'Economics', 'PA 6.1.7.A, 6.1.7.C, 6.1.7.D: Explain how limited resources and unlimited wants cause scarcity, define opportunity cost, and how positive and negative incentives affect behavior.', 3, '2026-10-14', 'us-pa'),
  ('pa.g7.sosyal.founding-documents', 'sosyal', 7, 'Constitutions, rights and rule of law', 'Civics and Government', 'PA 5.1.7.D, 5.1.7.E, 5.1.7.A: Summarize principles of the Declaration, Constitution and Bill of Rights and the framers'' roles, compare PA and US rights, and how rule of law protects.', 4, '2026-10-28', 'us-pa'),
  ('pa.g7.sosyal.physical-geography', 'sosyal', 7, 'Physical processes and regions', 'Geography', 'PA 7.2.7.A, 7.2.7.B: Explain the physical characteristics of places and regions and the processes, like plate movement, erosion and climate, that shape Earth''s surface.', 5, '2026-11-10', 'us-pa'),
  ('pa.g7.sosyal.us-pa-history', 'sosyal', 7, 'People and documents in US history', 'History', 'PA 8.3.7.A, 8.3.7.B, 8.2.7.A: Classify contributions of individuals and groups in US and Pennsylvania history, and the importance of key documents, artifacts and places.', 6, '2026-12-01', 'us-pa'),
  ('pa.g7.sosyal.branches-and-levels', 'sosyal', 7, 'Branches and levels of government', 'Civics and Government', 'PA 5.3.7.A, 5.3.7.B, 5.3.7.F: Compare powers of the three branches, the roles of local, state and national governments, and the different levels of the court system.', 7, '2026-12-15', 'us-pa'),
  ('pa.g7.sosyal.markets-and-prices', 'sosyal', 7, 'Markets, prices and economic systems', 'Economics', 'PA 6.2.7.B, 6.2.7.D, 6.2.7.G: Explain market competition, how price changes affect buyers and sellers, and how economic systems answer what, how and for whom to produce.', 8, '2027-01-12', 'us-pa'),
  ('pa.g7.sosyal.human-geography', 'sosyal', 7, 'Human geography and environment', 'Geography', 'PA 7.3.7.A, 7.4.7.A, 7.4.7.B: Describe population, culture, settlement and economic activities of regions, and how physical systems and people affect each other.', 9, '2027-01-26', 'us-pa'),
